<?php
namespace App\Modules\Accompagnement\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Accompagnement\Services\MissionAccess as Access;
use App\Modules\Tenancy\Services\OfficineAccess as Office;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class MissionFindingController extends Controller {
 private function mission(Request $r,string $id,bool $write=false):array{
  $office=(int)app('tenant.officine_id');Access::lockOffice($r,$office);
  $m=DB::table('support_missions as m')->join('support_requests as q','q.id','=','m.support_request_id')->where('q.officine_id',$office)->where('m.id',$id)->select('m.*')->first();
  abort_unless($m&&Access::allowed($r,$office,$m->id,$write,$write),404);
  if($write)abort_unless($m->status==='active',409,'Mission non active.');return [$office,$m];
 }
 private function rules():array{return ['title'=>['required','string','max:180','regex:/\S/u'],'fact'=>['required','string','max:5000','regex:/\S/u'],'category'=>['required','in:strength,improvement,gap,potential_nonconformity'],'presumed_cause'=>['nullable','string','max:3000'],'recommendation'=>['nullable','string','max:3000'],'observed_on'=>['required','date_format:Y-m-d','before_or_equal:'.now('Africa/Porto-Novo')->toDateString()]];}
 private function fields(array $d):array{return collect($d)->only(array_keys($this->rules()))->map(fn($v)=>is_string($v)?trim($v):$v)->all();}
 private function row(object $m,string $id):object{$f=DB::table('support_findings')->where('mission_id',$m->id)->where('id',$id)->lockForUpdate()->first();abort_unless($f,404);return $f;}
 public function index(Request $r,string $id){return DB::transaction(function()use($r,$id){[$office,$m]=$this->mission($r,$id);$lead=Access::allowed($r,$office,$m->id,true,true);$q=DB::table('support_findings')->where('mission_id',$m->id);if(!$lead)$q->where('status','shared');$rows=$q->orderByDesc('id')->get()->map(function($f){$f->source_snapshot=json_decode($f->source_snapshot,true);unset($f->request_key,$f->fingerprint);return $f;});return response()->json(['data'=>$rows,'can_lead'=>$lead,'action_integration_available'=>false])->header('Cache-Control','no-store');});}
 public function create(Request $r,string $id){$d=$r->validate($this->rules()+['diagnostic_id'=>['required','integer','min:1'],'question_key'=>['required','string','max:80'],'request_key'=>['required','string','min:16','max:80','regex:/^[A-Za-z0-9-]+$/'],'confirmed'=>['required','accepted']]);$fields=$this->fields($d);$fingerprint=hash('sha256',json_encode([$r->user()->id,(int)$d['diagnostic_id'],$d['question_key'],$fields]));return DB::transaction(function()use($r,$id,$d,$fields,$fingerprint){[$office,$m]=$this->mission($r,$id,true);$existing=DB::table('support_findings')->where('mission_id',$m->id)->where('request_key',$d['request_key'])->first();if($existing){abort_unless(hash_equals($existing->fingerprint,$fingerprint),409,'Clé déjà utilisée avec un autre contenu.');return response()->json(['id'=>$existing->id]);}
  $diagnostic=DB::table('support_diagnostics')->where('mission_id',$m->id)->where('id',$d['diagnostic_id'])->first();abort_unless($diagnostic,404);abort_unless(in_array($diagnostic->status,['submitted','shared'],true),409,'Soumettez le diagnostic pour figer la source avant de créer un constat.');
  $snapshot=json_decode($diagnostic->template_snapshot,true);$question=collect($snapshot['questions'])->firstWhere('key',$d['question_key']);abort_unless($question,422,'Question étrangère au diagnostic.');$answer=collect(json_decode($diagnostic->answers,true))->firstWhere('key',$d['question_key']);
  $finding=DB::table('support_findings')->insertGetId($fields+['mission_id'=>$m->id,'diagnostic_id'=>$diagnostic->id,'question_key'=>$d['question_key'],'source_snapshot'=>json_encode(['diagnostic_revision'=>$diagnostic->revision,'model_title'=>$snapshot['title'],'model_revision'=>$snapshot['revision'],'question'=>$question,'answer'=>$answer]),'request_key'=>$d['request_key'],'fingerprint'=>$fingerprint,'created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);Office::audit($r,$office,'support.finding.draft_created',['request_id'=>$m->support_request_id]);return response()->json(['id'=>$finding],201);});}
 public function save(Request $r,string $id,string $findingId){$d=$r->validate($this->rules()+['version'=>['required','integer','min:1']]);return DB::transaction(function()use($r,$id,$findingId,$d){[$office,$m]=$this->mission($r,$id,true);$f=$this->row($m,$findingId);abort_unless($f->status==='draft'&&$f->version===(int)$d['version'],409,'Constat figé ou périmé.');DB::table('support_findings')->where('id',$f->id)->update($this->fields($d)+['version'=>$f->version+1,'updated_at'=>now()]);Office::audit($r,$office,'support.finding.draft_saved',['request_id'=>$m->support_request_id]);return response()->json(['message'=>'Brouillon enregistré.']);});}
 public function share(Request $r,string $id,string $findingId){$d=$r->validate(['version'=>['required','integer','min:1'],'confirmed'=>['required','accepted']]);return DB::transaction(function()use($r,$id,$findingId,$d){[$office,$m]=$this->mission($r,$id,true);$f=$this->row($m,$findingId);abort_unless($f->status==='draft'&&$f->version===(int)$d['version'],409,'Constat figé ou périmé.');$source=DB::table('support_diagnostics')->where('mission_id',$m->id)->where('id',$f->diagnostic_id)->first();abort_unless($source&&$source->status==='shared',409,'Partagez d’abord le diagnostic source : le constat reprend son contenu.');DB::table('support_findings')->where('id',$f->id)->update(['status'=>'shared','version'=>$f->version+1,'shared_at'=>now(),'updated_at'=>now()]);Access::event($r,$m,$office,'finding_shared','Un constat a été partagé, sans qualification réglementaire automatique.');return response()->json(['message'=>'Constat partagé et figé.']);});}
}
